function moneyFlowVolume(bars) {
  return bars.map((b) => {
    if (b.volume == null || !Number.isFinite(b.volume)) return Number.NaN;
    if (b.high === b.low) return 0;
    return (2 * b.close - b.high - b.low) / (b.high - b.low) * b.volume;
  });
}
